elif op[0] == "es":
    # 全池唯一端点切换预约建立：形状/字段/数量/重复 id/端点/编码、
    # 时间范围与关系（now<=at、before<=at）及时钟倒退已在解析期及
    # 共用时钟块判 INPUT，INPUT 先于 BACKEND、BACKEND 先于 STATE。
    # 执行期仅按 items 顺序确认所有后端存在（首个未知报 BACKEND），
