        self.assertEqual(result["items"], [
            {"id": "b1", "endpoint": self.EP3, "cids": ["c1"]},
            {"id": "b2", "endpoint": self.EP4, "cids": ["c2"]},
        ])
        self.assertEqual(result["closed"], 2)

